import java.util.*;import com.koios.Constants;import com.koios.game.content.command.impl.PlayerCommands;import com.koios.game.content.questtab.impl.HelpQuestPage;import com.koios.game.model.player.Player;import com.koios.network.GamePacket;import com.koios.client.stream.Stream;
/** Local branding/navigation regression; no external integration is invoked. */
public final class ExileBrandingCheck {
 static int checks;static void check(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}
 static List<String> strings(Player p){List<String> text=new ArrayList<>();for(GamePacket packet:((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets){check(packet.getOpcode()!=129,"No URL-opening packet");if(packet.getOpcode()==126){byte[] bytes=new byte[packet.getSize()];packet.getBuffer().getBytes(packet.getBuffer().readerIndex(),bytes);Stream s=new Stream(bytes);String value=s.readString();check(s.method435()!=12000,"No legacy browser string channel");text.add(value);}}return text;}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("exilebrand",85);p.setAttribute("tutorial-stage",11);PrototypeIntegrationCheck.idle(p);check(Constants.SERVER_NAME.equals("Exile"),"Public server name Exile");check(Constants.class.getName().equals("com.koios.Constants"),"Package compatibility retained");PlayerCommands commands=new PlayerCommands();for(String command:new String[]{"commands","guide","guides","help","info","maps","craft","passives","auth","vote","register","advertise","rules","forums","updates","shop","donate","website","hiscores","claim"}){((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.clear();commands.execute(p,command);List<String> text=strings(p);check(!text.isEmpty(),"Local response for "+command);check(text.stream().noneMatch(t->t.contains("http:")||t.contains("https:")||t.contains("Koios")),"No obsolete branding/URLs for "+command);String tab=p.getAttribute("prototype-tab","");check(tab.equals(command.equals("maps")?"maps":command.equals("craft")?"craft":command.equals("passives")?"tree":"guide"),"Command routes to intended local panel "+command);}
 HelpQuestPage page=new HelpQuestPage();check(page.title().equals("Exile Guide"),"Help page title branded");for(int button=129003;button<=129007;button++){((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.clear();check(page.buttonClick(p,button),"Local help navigation button handled");strings(p);}((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.clear();page.write(p);check(strings(p).stream().anyMatch(t->t.contains("Exile")),"Help page writes in-game branding");check(!page.buttonClick(p,1),"Unknown help button inert");com.koios.util.UpdatePlayersOnline retired=new com.koios.util.UpdatePlayersOnline();retired.run();check(com.koios.util.UpdatePlayersOnline.class.getDeclaredFields().length==0,"Retired forum hook retains no endpoint, credential or scheduler fields");System.out.println("Passed "+checks+" Exile branding/local-navigation checks.");}
}
